import { Box, Tooltip, Typography } from "@mui/material";
import type { GridValidRowModel } from "@mui/x-data-grid";
import type { ParentWorkItem } from "../../../hooks/useParentWorkItems";
import type { IEntityReference } from "../../../models/EntityReference";
import type { IFeature } from "../../../models/Feature";
import { getWorkItemName } from "../../../utils/featureName";
import {
	CANNOT_FORECAST_SHORT,
	cannotBeForecast,
	cannotForecastReason,
} from "../../../utils/forecast/cannotForecast";
import type { DataGridColumn } from "../DataGrid/types";
import FeatureName from "../FeatureName/FeatureName";
import ForecastInfoList from "../Forecasts/ForecastInfoList";
import ParentWorkItemCell from "../ParentWorkItemCell/ParentWorkItemCell";
import ActiveWorkIndicator from "./ActiveWorkIndicator";
import FeatureMoveMenu from "./FeatureMoveMenu";
import type { FeatureOrderingBinding } from "./types";
import WarningsIndicator from "./WarningsIndicator";

// FeatureListDataGrid pins this column first, so every feature list renders the name the same way.
export const createNameColumn = (
	featureTerm: string,
): DataGridColumn<IFeature & GridValidRowModel> => ({
	field: "name",
	headerName: `${featureTerm} Name`,
	hideable: false,
	width: 300,
	flex: 1,
	renderCell: ({ row }) => (
		<FeatureName
			name={getWorkItemName(row.name, row.referenceId)}
			url={row.url ?? ""}
		/>
	),
});

export const createForecastsColumn = (
	headerName = "Forecasts",
): DataGridColumn<IFeature & GridValidRowModel> => ({
	field: "forecasts",
	headerName,
	width: 200,
	sortable: false,
	renderCell: ({ row }) => (
		<Box data-testid="feature-forecast-cell">
			{cannotBeForecast({ teamsWithoutForecast: row.teamsWithoutForecast }) ? (
				<Tooltip title={cannotForecastReason(row.teamsWithoutForecast ?? [])}>
					<Typography variant="body2" color="text.secondary">
						{CANNOT_FORECAST_SHORT}
					</Typography>
				</Tooltip>
			) : (
				<ForecastInfoList title={""} forecasts={row.forecasts} />
			)}
		</Box>
	),
});

// The value is the backend-supplied global position, never the row index - the grid may be filtered.
export const createPositionColumn = (
	headerLabel: string,
): DataGridColumn<IFeature & GridValidRowModel> => ({
	field: "position",
	headerName: headerLabel,
	width: 70,
	sortable: true,
	valueGetter: (_, row) => row.position,
	renderCell: ({ row }) => <span>{row.position ?? ""}</span>,
});

// The four gestures live behind one menu so a row gains one control, not four.
export const createFeatureOrderingActionsColumn = (
	binding: FeatureOrderingBinding,
): DataGridColumn<IFeature & GridValidRowModel> => ({
	field: "featureOrderingActions",
	headerName: "",
	width: 60,
	sortable: false,
	filterable: false,
	renderCell: ({ row }) => (
		<FeatureMoveMenu
			feature={row}
			gate={binding.resolveGate(row)}
			onMove={(target) => binding.onMove(row.id, target)}
			visibleNeighbours={binding.neighboursFor(row)}
		/>
	),
});

export const createStateColumn = (): DataGridColumn<
	IFeature & GridValidRowModel
> => ({
	field: "state",
	headerName: "State",
	width: 150,
	sortable: true,
	renderCell: ({ row }) => <span>{row.state}</span>,
});

export const createWarningsColumn = (): DataGridColumn<
	IFeature & GridValidRowModel
> => ({
	field: "warnings",
	headerName: "Warnings",
	type: "boolean",
	width: 90,
	sortable: true,
	valueGetter: (_, row) =>
		(row.stateCategory === "Done" && row.getRemainingWorkForFeature() > 0) ||
		row.isUsingDefaultFeatureSize,
	renderCell: ({ row }) => (
		<WarningsIndicator
			isDoneWithRemainingWork={
				row.stateCategory === "Done" && row.getRemainingWorkForFeature() > 0
			}
			isUsingDefaultFeatureSize={row.isUsingDefaultFeatureSize}
		/>
	),
});

export const createActiveWorkColumn = (
	getTeams: (row: IFeature) => IEntityReference[],
): DataGridColumn<IFeature & GridValidRowModel> => ({
	field: "activeWork",
	headerName: "Active Work",
	type: "boolean",
	width: 110,
	sortable: true,
	valueGetter: (_, row) => getTeams(row).length > 0,
	renderCell: ({ row }) => <ActiveWorkIndicator teams={getTeams(row)} />,
});

// Most features wait on nothing, so the cell stays blank in that case, the same way a missing
// position is left blank. A printed 0 would sit in the column looking like a number worth reading.
const renderDependsOnCount = (count: number | undefined) => {
	if ((count ?? 0) > 0) {
		return <span>{count}</span>;
	}

	return <span />;
};

export const createDependsOnColumn = (
	featuresTerm: string,
): DataGridColumn<IFeature & GridValidRowModel> => ({
	field: "dependsOnCount",
	headerName: `Depends On ${featuresTerm}`,
	width: 150,
	sortable: true,
	valueGetter: (_, row) => row.dependsOnCount,
	renderCell: ({ row }) => renderDependsOnCount(row.dependsOnCount),
});

export const createParentColumn = (
	parentMap: Map<string, ParentWorkItem>,
): DataGridColumn<IFeature & GridValidRowModel> => ({
	field: "parent",
	headerName: "Parent",
	width: 300,
	sortable: false,
	renderCell: ({ row }) => (
		<Box>
			<ParentWorkItemCell
				parentReference={row.parentWorkItemReference}
				parentMap={parentMap}
			/>
		</Box>
	),
});

import { render, screen } from "@testing-library/react";
import { MemoryRouter } from "react-router";
import { describe, expect, it, vi } from "vitest";
import type { IEntityReference } from "../../../models/EntityReference";
import { Feature } from "../../../models/Feature";
import { createForecastsColumn, createStateColumn } from "./columns";
import FeatureListDataGrid from "./FeatureListDataGrid";

let mockedPolicy: "SourceOrder" | "ManualOrder" = "SourceOrder";

vi.mock("../../../hooks/useFeatureOrdering", () => ({
	useFeatureOrdering: () => ({
		policy: mockedPolicy,
		positionColumnLabel: mockedPolicy === "ManualOrder" ? "Manual" : "#",
		// These tests are about the columns the grid injects, not about who may move a row - that verdict
		// is judged in useFeatureOrdering.moveGate.test.tsx and FeatureMoveMenu.test.tsx.
		resolveMoveGate: () => ({
			enabled: false,
			reason: "policy-off",
			blockingPortfolios: [],
		}),
		refresh: vi.fn(),
	}),
}));

vi.mock("../../../services/TerminologyContext", () => ({
	useTerminology: () => ({
		getTerm: (key: string) => {
			if (key === "feature") return "Feature";
			if (key === "features") return "Features";
			if (key === "workItems") return "Work Items";
			return "Unknown";
		},
	}),
}));

const createFeature = (
	overrides: Partial<{
		id: number;
		name: string;
		referenceId: string;
		stateCategory: string;
		remainingWork: { [key: number]: number };
		isUsingDefaultFeatureSize: boolean;
		position: number;
	}>,
): Feature => {
	const feature = new Feature();
	feature.id = overrides.id ?? 1;
	feature.name = overrides.name ?? "Test Feature";
	feature.referenceId = overrides.referenceId ?? "FTR-1";
	feature.stateCategory =
		(overrides.stateCategory as Feature["stateCategory"]) ?? "ToDo";
	feature.lastUpdated = new Date();
	feature.isUsingDefaultFeatureSize =
		overrides.isUsingDefaultFeatureSize ?? false;
	feature.projects = [];
	feature.remainingWork = overrides.remainingWork ?? { 1: 5 };
	feature.totalWork = { 1: 10 };
	feature.forecasts = [];
	feature.url = "";
	feature.state = overrides.stateCategory === "Done" ? "Closed" : "Active";
	feature.position = overrides.position;
	return feature;
};

const defaultColumns = [createForecastsColumn(), createStateColumn()];

describe("FeatureListDataGrid", () => {
	beforeEach(() => {
		localStorage.clear();
		Object.defineProperty(globalThis, "matchMedia", {
			writable: true,
			value: vi.fn().mockImplementation((query) => ({
				matches: false,
				media: query,
				onchange: null,
				addListener: vi.fn(),
				removeListener: vi.fn(),
				addEventListener: vi.fn(),
				removeEventListener: vi.fn(),
				dispatchEvent: vi.fn(),
			})),
		});
	});

	const features = [
		createFeature({
			id: 1,
			name: "Active Feature",
			referenceId: "FTR-1",
			stateCategory: "ToDo",
		}),
		createFeature({
			id: 2,
			name: "In Progress Feature",
			referenceId: "FTR-2",
			stateCategory: "Doing",
		}),
		createFeature({
			id: 3,
			name: "Done Feature",
			referenceId: "FTR-3",
			stateCategory: "Done",
			remainingWork: {},
		}),
	];

	it("should render the hide completed features toggle", () => {
		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={features}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
				/>
			</MemoryRouter>,
		);

		expect(
			screen.getByTestId("hide-completed-features-toggle"),
		).toBeInTheDocument();
		expect(screen.getByText("Hide Completed Features")).toBeInTheDocument();
	});

	it("should have toggle checked by default", () => {
		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={features}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
				/>
			</MemoryRouter>,
		);

		const toggle = screen.getByTestId("hide-completed-features-toggle");
		const switchInput = toggle.querySelector('input[type="checkbox"]');
		expect(switchInput).toBeChecked();
	});

	it("should hide completed features by default", async () => {
		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={features}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
				/>
			</MemoryRouter>,
		);

		// Active features should render via state column (2 non-done features)
		const activeElements = await screen.findAllByText("Active");
		expect(activeElements).toHaveLength(2);

		// Done feature state should not appear
		expect(screen.queryByText("Closed")).not.toBeInTheDocument();
	});

	it("should show completed features when toggle is unchecked", async () => {
		const { default: userEvent } = await import("@testing-library/user-event");
		const user = userEvent.setup();

		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={features}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
				/>
			</MemoryRouter>,
		);

		const toggle = screen.getByTestId("hide-completed-features-toggle");
		const switchInput = toggle.querySelector('input[type="checkbox"]');
		await user.click(switchInput as HTMLElement);

		expect(await screen.findByText("Closed")).toBeInTheDocument();
	});

	it("should save toggle preference to localStorage when changed", async () => {
		const { default: userEvent } = await import("@testing-library/user-event");
		const user = userEvent.setup();

		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={features}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
				/>
			</MemoryRouter>,
		);

		expect(localStorage.getItem("test-hide-completed")).toBe("true");

		const toggle = screen.getByTestId("hide-completed-features-toggle");
		const switchInput = toggle.querySelector('input[type="checkbox"]');
		await user.click(switchInput as HTMLElement);

		expect(localStorage.getItem("test-hide-completed")).toBe("false");
	});

	it("should load toggle preference from localStorage on mount", () => {
		localStorage.setItem("test-hide-completed", "false");

		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={features}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
				/>
			</MemoryRouter>,
		);

		const toggle = screen.getByTestId("hide-completed-features-toggle");
		const switchInput = toggle.querySelector('input[type="checkbox"]');
		expect(switchInput).not.toBeChecked();
	});

	it("should show a Done feature with remaining work when hideCompleted is true", async () => {
		const featuresWithDoneHavingRemainingWork = [
			createFeature({ id: 1, stateCategory: "ToDo" }),
			createFeature({
				id: 2,
				stateCategory: "Done",
				remainingWork: { 1: 3 },
			}),
		];

		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={featuresWithDoneHavingRemainingWork}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
				/>
			</MemoryRouter>,
		);

		// Both the ToDo (Active) and the Done-with-remaining-work (Closed) should appear
		const activeElements = await screen.findAllByText("Active");
		expect(activeElements).toHaveLength(1);
		expect(await screen.findByText("Closed")).toBeInTheDocument();
	});

	it("should hide a Done feature with no remaining work when hideCompleted is true", async () => {
		const featuresWithDoneNoRemaining = [
			createFeature({ id: 1, stateCategory: "ToDo" }),
			createFeature({
				id: 2,
				stateCategory: "Done",
				remainingWork: {},
			}),
		];

		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={featuresWithDoneNoRemaining}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
				/>
			</MemoryRouter>,
		);

		const activeElements = await screen.findAllByText("Active");
		expect(activeElements).toHaveLength(1);
		expect(screen.queryByText("Closed")).not.toBeInTheDocument();
	});

	it("should show warning icon for Done feature with remaining work", async () => {
		const featuresWithWarning = [
			createFeature({
				id: 1,
				stateCategory: "Done",
				remainingWork: { 1: 5 },
			}),
		];

		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={featuresWithWarning}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
				/>
			</MemoryRouter>,
		);

		const warningIcon = await screen.findByTestId(
			"warning-done-with-remaining-work",
		);
		expect(warningIcon).toBeInTheDocument();
	});

	it("should show warning icon for feature using default feature size", async () => {
		const featuresWithDefaultSize = [
			createFeature({
				id: 1,
				stateCategory: "ToDo",
				isUsingDefaultFeatureSize: true,
			}),
		];

		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={featuresWithDefaultSize}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
				/>
			</MemoryRouter>,
		);

		const warningIcon = await screen.findByTestId(
			"warning-default-feature-size",
		);
		expect(warningIcon).toBeInTheDocument();
	});

	it("should not show warning icon for Done feature with no remaining work", async () => {
		const featuresNoWarning = [
			createFeature({ id: 1, stateCategory: "ToDo" }),
			createFeature({
				id: 2,
				stateCategory: "Done",
				remainingWork: {},
			}),
		];

		localStorage.setItem("test-hide-completed", "false");

		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={featuresNoWarning}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
				/>
			</MemoryRouter>,
		);

		await screen.findByText("Closed");
		expect(
			screen.queryByTestId("warning-done-with-remaining-work"),
		).not.toBeInTheDocument();
	});

	it("should not show warning icon for non-Done feature with remaining work", async () => {
		const nonDoneFeatures = [
			createFeature({ id: 1, stateCategory: "Doing", remainingWork: { 1: 3 } }),
		];

		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={nonDoneFeatures}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
				/>
			</MemoryRouter>,
		);

		await screen.findAllByText("Active");
		expect(
			screen.queryByTestId("warning-done-with-remaining-work"),
		).not.toBeInTheDocument();
	});

	it("should show active work indicator when getActiveWorkTeams returns teams", async () => {
		const activeTeam: IEntityReference = { id: 1, name: "Team Alpha" };
		const featuresWithActiveWork = [
			createFeature({ id: 1, stateCategory: "Doing" }),
		];

		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={featuresWithActiveWork}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
					getActiveWorkTeams={() => [activeTeam]}
				/>
			</MemoryRouter>,
		);

		expect(
			await screen.findByTestId("active-work-indicator"),
		).toBeInTheDocument();
	});

	it("should show no-active-work indicator when getActiveWorkTeams returns empty", async () => {
		const featuresNoActiveWork = [
			createFeature({ id: 1, stateCategory: "Doing" }),
		];

		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={featuresNoActiveWork}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
					getActiveWorkTeams={() => []}
				/>
			</MemoryRouter>,
		);

		expect(await screen.findByTestId("no-active-work")).toBeInTheDocument();
	});

	it("should not show active work indicator when getActiveWorkTeams prop is not provided", async () => {
		const someFeatures = [createFeature({ id: 1, stateCategory: "Doing" })];

		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={someFeatures}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
				/>
			</MemoryRouter>,
		);

		await screen.findAllByText("Active");
		expect(
			screen.queryByTestId("active-work-indicator"),
		).not.toBeInTheDocument();
	});

	// AC-1.5 names only the Features view and the Portfolio Feature list; a whole-instance ordinal
	// inside a team- or delivery-scoped subset would misread, so the column is opt-in.
	const rankedFeatures = [
		createFeature({ id: 1, stateCategory: "ToDo", position: 17 }),
	];

	it("should not show the position column when the surface does not ask for it", async () => {
		const { container } = render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={rankedFeatures}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
				/>
			</MemoryRouter>,
		);

		await screen.findAllByText("Active");
		expect(container.querySelector('[data-field="position"]')).toBeNull();
		expect(screen.queryByText("17")).not.toBeInTheDocument();
	});

	it("should show the position column when the surface asks for it", async () => {
		render(
			<MemoryRouter>
				<FeatureListDataGrid
					features={rankedFeatures}
					columns={defaultColumns}
					storageKey="test-grid"
					hideCompletedStorageKey="test-hide-completed"
					showPosition
				/>
			</MemoryRouter>,
		);

		expect(await screen.findByText("17")).toBeInTheDocument();
	});

	// Epic 5375 AC-5.4 — the column names whoever owns the order, and the grid must render the heading
	// the ordering seam gives it rather than one of its own.
	it.each([
		["SourceOrder", "#"],
		["ManualOrder", "Manual"],
	] as const)(
		"should head the position column with %s's label",
		async (policy, expectedHeading) => {
			mockedPolicy = policy;

			render(
				<MemoryRouter>
					<FeatureListDataGrid
						features={rankedFeatures}
						columns={defaultColumns}
						storageKey="test-grid"
						hideCompletedStorageKey="test-hide-completed"
						showPosition
					/>
				</MemoryRouter>,
			);

			expect(
				await screen.findByRole("columnheader", { name: expectedHeading }),
			).toBeInTheDocument();
		},
	);
});

import { render, screen } from "@testing-library/react";
import { MemoryRouter } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { Feature, type IFeature } from "../../../models/Feature";
import { createDependsOnColumn, createStateColumn } from "./columns";
import FeatureListDataGrid from "./FeatureListDataGrid";

vi.mock("../../../hooks/useFeatureOrdering", () => ({
	useFeatureOrdering: () => ({
		policy: "SourceOrder",
		positionColumnLabel: "#",
		resolveMoveGate: () => ({
			enabled: false,
			reason: "policy-off",
			blockingPortfolios: [],
		}),
		refresh: vi.fn(),
	}),
}));

const SEEDED_TERMS: Record<string, string> = {
	feature: "Feature",
	features: "Features",
	blocked: "Blocked",
};

const terminology = vi.hoisted(() => ({
	terms: {} as Record<string, string>,
}));

vi.mock("../../../services/TerminologyContext", () => ({
	useTerminology: () => ({
		getTerm: (key: string) => terminology.terms[key] ?? "Unknown",
	}),
}));

beforeEach(() => {
	terminology.terms = { ...SEEDED_TERMS };
	localStorage.clear();
	Object.defineProperty(globalThis, "matchMedia", {
		writable: true,
		value: vi.fn().mockImplementation((query) => ({
			matches: false,
			media: query,
			onchange: null,
			addListener: vi.fn(),
			removeListener: vi.fn(),
			addEventListener: vi.fn(),
			removeEventListener: vi.fn(),
			dispatchEvent: vi.fn(),
		})),
	});
});

const feature = (overrides: Partial<IFeature> = {}): IFeature =>
	({
		id: 1,
		name: "Rebuild the search index",
		forecasts: [],
		teamsWithoutForecast: [],
		...overrides,
	}) as IFeature;

const renderCell = (row: IFeature) => {
	const column = createDependsOnColumn("Features");
	return render(column.renderCell?.({ row, value: row.dependsOnCount }));
};

describe("createDependsOnColumn", () => {
	it("shows how many Features this one is waiting on", () => {
		renderCell(feature({ dependsOnCount: 2 }));

		expect(screen.getByText("2")).toBeInTheDocument();
	});

	it("leaves the cell empty when the Feature waits on nothing", () => {
		const { container } = renderCell(feature());

		expect(container.textContent).toBe("");
	});

	it("reads a counted none as nothing too, never as a literal zero", () => {
		const { container } = renderCell(feature({ dependsOnCount: 0 }));

		expect(container.textContent).toBe("");
	});

	it("takes the vocabulary it is given rather than naming the concept itself", () => {
		expect(createDependsOnColumn("Epics").headerName).toBe("Depends On Epics");
	});

	it("never borrows the word an instance may already have renamed for board-blocked work", () => {
		expect(createDependsOnColumn("Features").headerName).not.toMatch(/block/i);
	});

	it("stays sortable, so a list can be read waiting-most first", () => {
		expect(createDependsOnColumn("Features").sortable).toBe(true);
	});

	it("sorts on the number itself, not on what the cell happens to print", () => {
		const column = createDependsOnColumn("Features");

		expect(
			column.valueGetter?.(undefined, feature({ dependsOnCount: 3 })),
		).toBe(3);
	});
});

const featureRow = (dependsOnCount?: number): Feature => {
	const row = new Feature();
	row.id = 1;
	row.name = "Rebuild the search index";
	row.referenceId = "FTR-1";
	row.stateCategory = "ToDo";
	row.state = "Active";
	row.lastUpdated = new Date();
	row.isUsingDefaultFeatureSize = false;
	row.projects = [];
	row.remainingWork = { 1: 5 };
	row.totalWork = { 1: 10 };
	row.forecasts = [];
	row.url = "";
	row.dependsOnCount = dependsOnCount;
	return row;
};

const renderGrid = (dependsOnCount = 2) =>
	render(
		<MemoryRouter>
			<FeatureListDataGrid
				features={[featureRow(dependsOnCount)]}
				columns={[createStateColumn()]}
				storageKey="depends-on-shared-grid"
				hideCompletedStorageKey="depends-on-shared-grid-hide-completed"
			/>
		</MemoryRouter>,
	);

describe("the same count is read on both Feature lists, because there is only one of them", () => {
	// Neither Feature list can supply this column: the shared grid composes it, so there is one
	// definition to disagree with itself. A caller passing only its own columns still gets it.
	it("comes from the shared grid, so no surface can hand in its own version", () => {
		renderGrid();

		expect(
			screen.getByRole("columnheader", { name: "Depends On Features" }),
		).toBeInTheDocument();
		expect(screen.getByText("2")).toBeInTheDocument();
	});
});

describe("the column speaks the instance's own vocabulary", () => {
	it("names the thing being waited on with the word this instance chose", () => {
		terminology.terms.features = "Epics";

		renderGrid();

		expect(
			screen.getByRole("columnheader", { name: "Depends On Epics" }),
		).toBeInTheDocument();
	});

	// An instance can rename what it calls held-up work, and one screen carrying that word in two
	// meanings is unreadable. Whatever the instance chose, this column must not have borrowed it.
	it("never borrows the word this instance keeps for held-up work", () => {
		terminology.terms.blocked = "Impeded";

		const { container } = renderGrid();
		const columnCells = container.querySelectorAll(
			'[data-field="dependsOnCount"]',
		);

		expect(columnCells.length).toBeGreaterThan(0);
		for (const cell of columnCells) {
			expect(cell.textContent).not.toMatch(/impeded/i);
			expect(cell.textContent).not.toMatch(/block/i);
		}
	});
});
